SELECT CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(unit_price * quantity) AS revenue, COUNT(*) AS order_item_count, ROUND(STDDEV(quantity), 2) AS stddev_quantity FROM order_items GROUP BY CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 110 THEN 'mid' ELSE 'low' END
